
const icons=['<path d="M3 10 12 3l9 7v11h-6v-7H9v7H3z"/>','<rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8"/>','<path d="M4 20V11h4v9M10 20V4h4v16M16 20V8h4v12"/>','<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c6 6 6 12 0 18-6-6-6-12 0-18"/>','<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>'];
const $=id=>document.getElementById(id),clamp=(v,l=0,h=100)=>Math.max(l,Math.min(h,v)),pick=a=>a[Math.floor(Math.random()*a.length)],rand=(a,b)=>a+Math.random()*(b-a),fmt=n=>Math.round(n).toLocaleString(),money=n=>'$'+fmt(n),compact=n=>n>=1e6?(n/1e6).toFixed(1)+'M':n>=1e3?(n/1e3).toFixed(1)+'K':fmt(n),esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tierNames=['Unknown','Emerging','Breakout','Star','Superstar','Global star','Global icon'];
const thresholds=[0,1000,25000,250000,2000000,20000000,100000000];
const tier=f=>thresholds.reduce((t,n,i)=>f>=n?i:t,0);
const genres=['Hip-hop','R&B','Pop','Rock','Country','Electronic','Latin','Afrobeats','Jazz','Gospel','Reggae','Indie folk','K-pop','Metal'];
const titles={song:[['After','Before','Beyond','Under','Without','Chasing','Finding','Only','Midnight','Last'],['the Rain','the Lights','Home','Tomorrow','the Noise','Your Shadow','a Promise','the Silence','the Sun','the City']],album:[['Letters from','The Weight of','A Season of','Life After','The Art of','Everything About','Somewhere Beyond','Nothing but','A World of','Made of'],['Midnight','Becoming','Silence','Gold','Yesterday','the Fall','Us','Daylight','Pressure','Dreams']]};
function generate(kind,current=''){let value;do{value=kind==='artist'?pick(['Jade','Saint','Nova','Kairo','Lux','Sol','Milo','Indigo','Remy','Arlo','Zion','Skye','Ace','Juno','Rio','Lyric'])+' '+pick(['Vale','West','Monroe','Saint','Reign','Wilde','Ash','Cole','Lane','Banks','Gray','Stone','Rose','North','Wells','Dream']):pick(titles[kind][0])+' '+pick(titles[kind][1]);}while(value===current);return value}
function fillName(id,kind){$(id).value=generate(kind,$(id).value)}
const seeds=[['NOVA VALE','Pop',180000000],['ORION SAINT','R&B',120000000],['SOL REYES','Latin',65000000],['SEOUL NIGHTS','K-pop',42000000],['ATLAS RED','Rock',29000000],['SAINT REIGN','Hip-hop',11500000],['AMARA SUN','Afrobeats',8000000],['LUCAS REED','Country',4300000],['NEON HARBOR','Electronic',2600000],['IVY MONROE','R&B',850000],['JUNE STATIC','Rock',750000],['ZION ROOTS','Reggae',410000],['ELLA NORTH','Country',300000],['MILES BLUE','Jazz',140000],['GRACE RIVERS','Gospel',80000],['IRON HOLLOW','Metal',45000],['MARLOW','Indie folk',22000],['KAI MONROE','Pop',6500],['RIO ASH','Hip-hop',2400],['LENA WELLS','Electronic',640],['JUNO GRAY','R&B',230],['ACE LANE','Hip-hop',85],['LUZ MAR','Latin',350],['KOFI DAWN','Afrobeats',110]];
function makeWorld(){return seeds.map(([name,genre,fans],i)=>({id:i,name,genre,fans,skill:clamp(30+tier(fans)*10+rand(-8,8)),reputation:clamp(12+tier(fans)*13+rand(-5,5)),relation:0,lastTalk:0,lastNegotiate:0,discount:0,nextRelease:2+i%6,catalog:[{title:generate('song'),type:'Single',week:-i%4,base:Math.round(fans*rand(.5,.9)),streams:Math.round(fans*rand(.3,.7)),total:Math.round(fans*rand(2,6)),factor:1}],weekly:0}))}
function fresh(){return {pacingVersion:1,chartRulesVersion:2,chartWeek:1,name:'Solace',genre:'Hip-hop',background:'Bedroom artist',week:1,cash:650,fans:42,energy:85,skill:35,reputation:8,stage:25,loyalty:20,ap:6,songs:[],albums:[],draft:null,boost:0,streams:0,total:0,started:false,world:makeWorld(),feed:[],history:[{week:1,text:'Your story starts here. Six time slots. One first impression.'}]}}
let saveReady=false,saveBusy=false,saveConflict=false,saveTimer,lastSaved='',saveEtag=null;
let s=fresh(),tab='Home',industryTab='Artists',filter='All',genreFilter='All';
function toast(t){$('toast').textContent=t;$('toast').hidden=false;clearTimeout(window.tt);window.tt=setTimeout(()=>$('toast').hidden=true,3500)}function log(t){s.history.unshift({week:s.week,text:t});s.history=s.history.slice(0,100)}function go(t){tab=t;render();window.scrollTo(0,0)}function spend(energy=10,cost=0){if(!saveReady||saveConflict)return false;if(!s.ap){toast('Your week is full. Advance for six new slots.');return false}if(s.energy<energy){toast('Rest to recover energy first.');return false}if(cost>0&&s.cash<cost){toast('Not enough cash. Work a shift or save up.');return false}s.started=true;s.ap--;s.energy-=energy;s.cash=Math.round((s.cash-cost)*100)/100;return true}
function modal(html){$('modal').innerHTML=`<button class="close" onclick="$('modal').close()" aria-label="Close">×</button>${html}`;if(!$('modal').open)$('modal').showModal()}
function render(){if(!saveReady)return;$('week').textContent='YEAR '+(Math.floor((s.week-1)/52)+1)+' · WEEK '+((s.week-1)%52+1);$('time').textContent=s.ap+' of 6 time slots available';$('nav').innerHTML=['Studio','Industry','Home','Career','Artist'].map((t,i)=>`<button class="${(tab===t||(tab==='Training'&&t==='Artist'))?'active':''} ${t==='Home'?'nav-home':''}" aria-current="${(tab===t||(tab==='Training'&&t==='Artist'))?'page':'false'}" onclick="go('${t}')"><svg viewBox="0 0 24 24" aria-hidden="true">${icons[{Home:0,Studio:1,Career:2,Industry:3,Artist:4}[t]]}</svg>${t}</button>`).join('');$('app').innerHTML=({Home:home,Studio:studio,Career:career,Industry:industry,Artist:artist,Training:training}[tab])();$('app').className='screen-'+tab.toLowerCase();queueSave()}
function head(label,title,right=''){return `<div class="heading"><div><div class="eyebrow">${label}</div><h1>${title}</h1></div>${right}`+'</div>'}
function stats(){return `<div class="stats">${[['Cash',money(s.cash)],['True fans',compact(s.fans)],['Last week’s streams',compact(s.streams)],['Energy',s.energy+'<span style="font-size:15px" class="muted"> /100</span>']].map(([l,v])=>`<div class="stat"><label>${l}</label><strong>${v}</strong></div>`).join('')}</div>`}
function home(){let next=[100,250,1000,10000,100000,1000000,10000000].find(n=>n>s.fans)||Math.ceil((s.fans+1)/10000000)*10000000,released=s.songs.filter(x=>x.released);return `<div class="home-heading"><div><span class="eyebrow">Your career</span><h1>${esc(s.name)}</h1></div><span class="pill">${tierNames[tier(s.fans)]} · Independent</span></div>`+homeStats()+nextStep()+`<div class="grid"><div><section class="card feature"><div class="eyebrow">${s.draft?'In the studio':released.length?'Your next era':'Chapter 01 · The beginning'}</div><h2>${s.draft?esc(s.draft.title):released.length?'Keep them listening.':'From nobody to somebody.'}</h2><p>${s.draft?'A record in progress. A story only you can tell.':released.length?'Make your next record, build a relationship, or give your catalog a push.':'Write your first record. Build your circle. Find your people.'}</p><button class="primary" onclick="${s.started?"go('Studio')":"setup()"}">${s.started?(s.draft?'Continue recording':'Enter the studio'):'Create your artist'}</button></section><div class="sectionhead"><h2>This week is yours</h2><span class="fine">1 slot each</span></div><div class="actions"><button class="action" onclick="action('work')">Work a shift<small>+$180 · −15 energy</small></button><button class="action training-entry" onclick="go('Training')">Training & stats<small>Improve craft · Build stage presence</small></button><button class="action" onclick="action('gig')">Play an open mic<small>+$30 · +8 fans · −20 energy</small></button><button class="action" onclick="action('rest')">Rest & reset<small>Recover 30 energy</small></button></div></div><div><section class="card"><div class="sectionhead"><h2>Your next milestone</h2><span class="tier">${tierNames[tier(s.fans)]}</span></div><p>${compact(s.fans)} / ${compact(next)} true fans</p><div class="bar"><i style="width:${Math.min(100,s.fans/next*100)}%"></i></div><p class="fine">${tier(s.fans)<tierNames.length-1?'Next: '+tierNames[tier(s.fans)+1]:'Build your legacy'}. Career tiers follow your fanbase. Charts follow weekly song streams.</p><button class="secondary" onclick="go('Industry')">Meet the industry</button></section><section class="card"><h2>Recently</h2>${s.history.slice(0,3).map(x=>`<div class="story"><small>WEEK ${x.week}</small>${esc(x.text)}</div>`).join('')}</section></div></div>`}
function action(a){if(a==='rest'&&s.energy===100){toast('You’re fully rested. Save that time slot for something else.');return}if(a==='practice'&&s.skill===100){toast('Your craft is already at its maximum.');return}if(a==='promo'&&s.boost>0){toast('Your campaign is already running for this week.');return}if(a==='rest'){if(!spend(0))return;s.energy=clamp(s.energy+30);log('You recovered up to 30 energy.')}if(a==='work'){if(!spend(15))return;s.cash+=180;log('A shift paid $180. A little more runway.')}if(a==='practice'){if(!spend(10))return;s.skill=clamp(s.skill+4);log('Craft improved by 4. Your next session will benefit.')}if(a==='gig'){if(!spend(20))return;s.cash+=30;s.fans+=8;s.stage=clamp(s.stage+3);log('Eight new fans, $30 earned, and more stage experience.')}if(a==='promo'){if(!s.songs.some(x=>x.released)){toast('Release a song first.');return}if(!spend(10,50))return;s.boost=.35;log('A $50 campaign adds 35% to catalog streams this week.')}render()}
function nameInput(id,kind,value='',placeholder=''){return `<div class="namefield"><input id="${id}" name="${id}" value="${esc(value)}" placeholder="${placeholder}" maxlength="55" required><button class="secondary" type="button" onclick="fillName('${id}','${kind}')">Shuffle</button></div>`}
function studio(){let d=s.draft;return head('Create · Record · Release','The studio.',`<span class="pill">${esc(s.genre)}</span>`)+metricRail([['Craft',s.skill+'/100'],['Energy',s.energy+'/100'],['Time',s.ap+' slots'],['Cash',money(s.cash)]])+`<div class="grid"><section class="card">${d?`<span class="tier">${esc(d.mood)} · Work in progress</span><h1 class="wrap" style="margin:16px 0">${esc(d.title)}</h1>${['Writing','Recording','Mixing'].map((x,i)=>`<div class="step ${d.steps>i?'done':''}">${d.steps>i?'✓':'○'} ${x}</div>`).join('')}<div class="row"><span>Record quality</span><strong>${d.quality}/100</strong></div><p class="fine">Expected debut baseline: ${compact(reach(d))} streams before reception and promotion. Quality improves your odds; no release is a guaranteed hit.</p><div class="highlightbox">${d.feature?'Featuring '+esc(d.feature.name)+' · Fee paid '+money(d.feature.fee):'Want a guest verse? Meet artists in Industry before finishing this record.'}</div><div class="controls">${d.steps<3?`<button class="primary" onclick="progressSong()">${d.steps===1?'Record · $40':'Mix · $30'}</button>`:`<button class="primary" onclick="finishSong(true)">Release single · $20</button><button class="secondary" onclick="finishSong(false)">Save for album</button>`}</div><p class="fine">${d.steps<3?'1 slot · 15 energy': 'Release: 1 slot, 5 energy. Saving a finished track uses no extra slot.'}</p>`:`<h2>A blank page. Your next record.</h2><p>Write it yourself, or shuffle for a starting point.</p><form class="form" onsubmit="newSong(event)"><label>Song title${nameInput('songtitle','song','','After the Last Shift')}</label><label>Creative direction<select name="mood"><option>Personal / storytelling</option><option>Catchy / radio-ready</option><option>Raw / experimental</option></select></label><button class="primary">Start writing · 1 slot</button><span class="fine">A single takes 4 slots across writing, recording, mixing, and release. Total: $90 and 45 energy. You can spread these across weeks.</span><details><summary class="fine">What does creative direction change?</summary><p class="fine">Personal converts more listeners into fans. Catchy gives 20% more debut reach. Experimental trades consistency for a wider range of outcomes.</p></details></form>`}</section><div><section class="card"><div class="eyebrow">Build an era</div><h2 style="margin-top:10px">Your next album</h2><p>Combine at least 3 finished tracks into an album. Released singles can join, but each track can belong to only one album.</p><button class="secondary" onclick="albumForm()">Assemble an album</button><p class="fine">$100 release fee · 1 slot · 10 energy</p></section><section class="card"><h2>On the shelf</h2>${s.songs.filter(x=>!x.released).length?s.songs.filter(x=>!x.released).map(x=>`<div class="row"><div><h3>${esc(x.title)}</h3><span class="fine">Quality ${x.quality}${x.feature?' · feat. '+esc(x.feature.name):''}</span></div><button class="secondary" onclick="releaseShelf(${x.id})">Release · $20</button></div>`).join(''):'<p>Finished tracks saved for an album will appear here.</p>'}</section></div></div>`}
function newSong(e){e.preventDefault();if(s.draft)return;let f=new FormData(e.target);if(!spend(10))return;s.started=true;s.draft={id:Date.now()+Math.random(),title:f.get('songtitle').trim()||generate('song'),mood:f.get('mood'),steps:1,quality:Math.round(20+s.skill*.65),feature:null};log('Started writing “'+s.draft.title+'”.');render()}
function progressSong(){let d=s.draft;if(!d||d.steps>=3||!spend(15,d.steps===1?40:30))return;d.steps++;d.quality=clamp(Math.round(d.quality+6+s.skill*.06));render()}
function finishSong(release){let d=s.draft;if(!d||d.steps!==3)return;if(release&&!spend(5,20))return;const song={...d,released:release?s.week:null,streams:0,total:0,peak:null,album:null};s.songs.push(song);s.draft=null;log('“'+song.title+'” '+(release?'is out. Results arrive at the end of this week.':'is ready for your album.'));render();toast(release?'Single released. Advance the week for results.':'Finished track saved.')}
function releaseShelf(id){let x=s.songs.find(x=>x.id===id);if(!x||x.released||!spend(5,20))return;x.released=s.week;log('“'+x.title+'” is out.');render()}
function albumForm(){let eligible=s.songs.filter(x=>!x.album);modal(`<div class="eyebrow">Your next era</div><h2>Assemble an album.</h2><form class="form" onsubmit="releaseAlbum(event)"><label>Album title${nameInput('albumtitle','album')}</label><p class="fine">Select at least 3 tracks. Existing singles retain their streams; new tracks debut together.</p>${eligible.length?eligible.map(x=>`<label class="row" style="justify-content:flex-start"><input style="width:20px;margin:0" type="checkbox" name="track" value="${x.id}"><span>${esc(x.title)} <small class="muted">${x.released?'Released single':'Unreleased'}</small></span></label>`).join(''):'<p>Finish some tracks in the studio first.</p>'}<button class="primary" ${eligible.length<3?'disabled':''}>Release album · $100</button><span class="fine">1 slot · 10 energy</span></form>`)}
function releaseAlbum(e){e.preventDefault();let f=new FormData(e.target),ids=f.getAll('track').map(Number),tracks=s.songs.filter(x=>ids.includes(x.id)&&!x.album);if(tracks.length<3){toast('Choose at least 3 finished tracks.');return}if(!spend(10,100))return;let a={id:Date.now(),title:f.get('albumtitle').trim()||generate('album'),week:s.week,tracks:tracks.map(x=>x.id)};tracks.forEach(x=>{x.album=a.id;if(!x.released)x.released=s.week;x.albumBoost=s.week});s.albums.push(a);log('Released “'+a.title+'”, a '+tracks.length+'-track album.');$('modal').close();tab='Career';render()}
function outcome(f){return f<.65?'Flop':f>=1.5?'Hit':'On target'}
const CHART_FLOOR=250000,CHART_SIZE=100;
function widerIndustry(){const week=s.chartWeek??Math.max(1,s.week-1);const first=['Luna','Cedar','Apollo','Ruby','Dante','Willow','Elio','Sable','Raven','Nico','Violet','Ocean','Remi','Arden','Flora'];const last=['Echo','Coast','Bloom','Fox','Ray','Moon','King','Waves','Hart','Wren'];return Array.from({length:150},(_,i)=>{let era=Math.floor((week+i%8)/8),swing=.82+.36*(.5+.5*Math.sin(i*2.7+week*.61));return {title:titles.song[0][(i+era)%10]+' '+titles.song[1][(Math.floor(i/10)+era*3)%10],artist:first[i%15]+' '+last[Math.floor(i/15)],tier:i<20?'Global star':i<75?'Superstar':'Star',streams:Math.round((100000+12000000*Math.pow(1-i/150,3))*swing),background:true}})}
function chart(){return widerIndustry().concat(s.world.flatMap(a=>a.catalog.filter(x=>x.type==='Single').map(x=>({...x,artist:a.name,tier:tierNames[tier(a.fans)]}))),s.songs.filter(x=>x.released&&x.total>0).map(x=>({...x,artist:s.name,tier:tierNames[tier(s.fans)],you:true}))).filter(x=>x.streams>=CHART_FLOOR).sort((a,b)=>b.streams-a.streams).slice(0,CHART_SIZE)}
function chartPosition(track){let i=chart().findIndex(x=>x.you&&x.id===track.id);return i<0?null:i+1}
function migrateCharts(){if(s.chartRulesVersion===2)return;for(const track of s.songs){if(track.peak)track.legacyPeak=track.peak;track.peak=null} s.chartRulesVersion=2;s.chartWeek=Math.max(1,s.week-1);log('Global Top 100 now includes the wider industry. Earlier prototype peaks are kept in your release details.');}

function career(){let songs=s.songs.filter(x=>x.released);return head('Your music in the world','Your catalog.',`<span class="pill">${songs.length} songs · ${s.albums.length} albums</span>`)+metricRail([['Weekly plays',compact(s.streams)],['Lifetime plays',compact(s.total)],['Fans',compact(s.fans)],['Reputation',s.reputation+'/100']])+`<div class="grid"><section class="card"><div class="sectionhead"><h2>Discography</h2><button class="secondary" onclick="go('Studio')">New music</button></div>${songs.length?songs.slice().reverse().map(x=>`<div class="track"><span class="recordno">${x.album?'ALB':'SGL'}</span><div><h3>${esc(x.title)}</h3><span class="fine">${x.feature?'feat. '+esc(x.feature.name)+' · ':''}${x.total?outcome(x.factor):'Awaiting debut'}${chartPosition(x)?' · #'+chartPosition(x):x.total?' · Uncharted':''}${x.peak===1?' · Chart topper':x.peak?' · Peak #'+x.peak:''}</span><div class="fine">${compact(x.streams)} this week · ${compact(x.total)} total</div>${x.legacyPeak?`<p class="fine">Earlier prototype peak: #${x.legacyPeak} (old chart rules)</p>`:''}${x.breakdown?`<details><summary class="fine">Why this result?</summary><p class="fine">${esc(x.breakdown)}</p></details>`:''}</div>${x.factor?`<span class="badge">${x.factor.toFixed(1)}×</span>`:''}</div>`).join(''):'<div class="empty"><h3>Your first era starts here.</h3><p>Release a single or build an album.</p></div>'}${s.albums.length?'<h2 style="margin-top:24px">Albums</h2>'+s.albums.map(a=>{let ts=s.songs.filter(x=>a.tracks.includes(x.id));return `<div class="row"><div><h3>${esc(a.title)}</h3><span class="fine">${ts.length} tracks · Week ${a.week}</span></div><strong>${compact(ts.reduce((n,x)=>n+x.total,0))} total</strong></div>`}).join(''):''}</section><div><section class="card"><h2>What counts as a hit?</h2><p>A debut below <strong>0.65×</strong> its expected audience is a flop. At <strong>1.5×</strong> or higher, it’s a hit. Number one on the global song chart earns “chart topper.”</p><p class="fine">A superstar’s flop can still dwarf an unknown artist’s hit. The multiplier measures performance relative to your reach at release.</p></section><section class="card"><h2>Give it a push</h2><p>A $50 campaign adds 35% to this week’s streams only. One campaign per week.</p><button class="secondary" onclick="action('promo')">Promote catalog · $50</button><p class="fine">1 slot · 10 energy. Simulated royalty: $0.50 per stream.</p></section></div></div>`}
function relationship(a){return a.relation<=-40?'Beef':a.relation<0?'Tense':a.relation<30?'Unfamiliar':a.relation<60?'Friendly':a.relation<85?'Close':'Inner circle'}
function baseFee(a){let t=tier(a.fans);return Math.round([80,900,5000,25000,140000,650000,2000000][t]*(.65+a.reputation/100)*Math.pow(Math.max(1,a.fans/Math.max(500,thresholds[t])),.18)/10)*10}
function freeEligible(a){return accessible(a)&&a.relation>=(tier(a.fans)>=5?98:90)&&s.reputation>=a.reputation-10}
function quote(a){if(freeEligible(a))return 0;return Math.max(10,Math.round(baseFee(a)*(1-Math.max(-60,a.relation)*.006)*(1-a.discount)/10)*10)}
function featureNeeds(a){let t=tier(a.fans);return {fans:t>=2?thresholds[t-2]:0,rep:Math.max([0,5,15,30,48,65,82][t],Math.round(a.reputation)-25),relation:[0,0,0,15,30,50,70][t]}}
function accessible(a){let n=featureNeeds(a);return a.relation>-40&&s.fans>=n.fans&&s.reputation>=n.rep&&a.relation>=n.relation}
function featureRequirements(a){let n=featureNeeds(a);return `<div class="requirements">${[['Fans',s.fans,n.fans,compact],['Reputation',s.reputation,n.rep,fmt],['Relationship',a.relation,n.relation,fmt]].map(([label,v,min,format])=>`<div><span>${v>=min?'✓':'○'} ${label}</span><strong>${format(v)} / ${format(min)}</strong></div>`).join('')}</div>`}

function profile(id){let a=s.world[id],fee=quote(a),blocked=a.relation<=-40,access=accessible(a);modal(`<div class="eyebrow">${tierNames[tier(a.fans)]} · ${esc(a.genre)}</div><h2>${esc(a.name)}</h2><p>${compact(a.fans)} fans · ${compact(a.catalog.reduce((n,x)=>n+x.streams,0))} weekly streams</p><div class="row"><span>${relationship(a)}</span><strong class="${a.relation<0?'bad':'highlight'}">${a.relation>0?'+':''}${a.relation} / 100</strong></div><p class="fine">Talk builds trust. Support helps faster. Beef damages trust, raises fees, and at −40 shuts collaborations down.</p><div class="controls"><button class="secondary" ${a.lastTalk===s.week?'disabled':''} onclick="social(${id},'talk')">Talk · 1 slot</button><button class="secondary" ${a.lastTalk===s.week?'disabled':''} onclick="social(${id},'support')">Support · $25</button><button class="secondary" ${a.lastTalk===s.week?'disabled':''} onclick="social(${id},'beef')">Start beef</button>${a.relation<0?`<button class="secondary" ${a.lastTalk===s.week?'disabled':''} onclick="social(${id},'apologize')">Apologize</button>`:''}</div><p class="fine">One social interaction per artist per week. Each uses 1 slot and 5 energy.</p><hr style="border:0;border-top:1px solid var(--line);margin:23px 0"><h3>Feature offer</h3><p class="fine">Artist reputation: ${fmt(a.reputation)}/100. Audience and reputation set the base price; friendship and negotiation can reduce it.</p><div class="quote">${fee===0?'On the house':money(fee)}</div><p class="fine">Standard fee ${money(baseFee(a))} · ${a.discount?'Negotiated discount active':'Relationship-adjusted quote'}</p><p>${blocked?'They won’t collaborate while you’re beefing. Repair the relationship first.':!access?'Meet all three requirements below before they will consider your record.':freeEligible(a)?'They trust you enough to waive the fee.':'They’re open to a feature. The price reflects your relationship.'}</p>${featureRequirements(a)}<div class="controls"><button class="secondary" ${blocked||!access||a.lastNegotiate===s.week?'disabled':''} onclick="negotiate(${id})">Negotiate · 1 slot</button><button class="primary" ${blocked||!access||!s.draft||!!s.draft.feature||s.cash<fee?'disabled':''} onclick="bookFeature(${id})">${fee===0?'Accept free feature':'Book · '+money(fee)}</button></div><p class="fine">${!s.draft?'Start a song in Studio to attach a feature.':s.draft.feature?'Your current song already has a guest.':'Booking attaches the artist to your current song. Fee is charged immediately; booking itself uses no extra slot.'} A guest expands reach but does not guarantee a hit.</p><h3 style="margin-top:24px">Recent releases</h3>${a.catalog.slice(-3).reverse().map(x=>`<div class="row"><div><strong>${esc(x.title)}</strong><div class="fine">${x.type} · ${outcome(x.factor)}</div></div><span>${compact(x.streams)} / wk</span></div>`).join('')}`)}
function social(id,kind,confirmed=false){if(kind==='beef'&&!confirmed){modal(`<h2>Call out ${esc(s.world[id].name)}?</h2><p>This costs one time slot and 5 energy. Relationship falls by 35 and fan loyalty and reputation by 2. Feature fees rise; at −40 they refuse to collaborate.</p><div class="controls"><button class="secondary" onclick="profile(${id})">Keep the peace</button><button class="primary" onclick="social(${id},'beef',true)">Start beef</button></div>`);return}let a=s.world[id];if(a.lastTalk===s.week)return;if(!spend(5,kind==='support'?25:0))return;let delta=kind==='beef'?-35:kind==='apologize'?20:kind==='support'?15:Math.round(rand(7,12));if(delta>0&&kind!=='apologize')delta=Math.max(1,Math.round(delta/(1+Math.max(0,tier(a.fans)-tier(s.fans))*.5))); a.relation=clamp(a.relation+delta,-100,100);a.lastTalk=s.week;if(kind==='beef'){a.discount=0;s.loyalty=clamp(s.loyalty-2);s.reputation=clamp(s.reputation-2);log('You called out '+a.name+'. Relationship fell by 35; loyalty and reputation fell by 2.')}else log((kind==='apologize'?'You apologized to ':kind==='support'?'You supported ':'You talked with ')+a.name+'. Relationship +'+delta+'.');render();profile(id)}
function negotiate(id){let a=s.world[id];if(a.lastNegotiate===s.week||a.relation<=-40||!accessible(a)||!spend(5))return;a.lastNegotiate=s.week;let chance=clamp(35+a.relation*.4+(s.reputation-a.reputation)*.35-Math.max(0,tier(a.fans)-tier(s.fans))*5,10,90);if(Math.random()*100<chance){a.discount=Math.min(.4,a.discount+.15);log(a.name+' agreed to a lower feature fee.');toast('Negotiation landed. Your quote is lower.')}else{a.relation=clamp(a.relation-3,-100,100);log(a.name+' declined the offer. Relationship −3.');toast('They declined. You can try again next week.')}render();profile(id)}
function bookFeature(id){if(!saveReady||saveConflict)return;let a=s.world[id],fee=quote(a);if(!s.draft||s.draft.feature||a.relation<=-40||!accessible(a)||s.cash<fee)return;s.cash-=fee;s.draft.feature={id:a.id,name:a.name,fans:a.fans,fee};a.relation=clamp(a.relation+5,-100,100);a.discount=0;log(a.name+' joined “'+s.draft.title+'” for '+(fee?money(fee):'free')+'.');$('modal').close();render();toast('Feature booked. Finish your record in Studio.')}
function industry(){let tabs=['Artists','Charts','New releases'];let top=head('A living music scene','The industry.')+`<div class="chips">${tabs.map(x=>`<button class="${industryTab===x?'selected':''}" onclick="industryTab='${x}';render()">${x}</button>`).join('')}</div>`;if(industryTab==='Charts'){let list=chart();return top+`<section class="card"><div class="sectionhead"><div><h2>Global Top 100</h2><p class="fine">Week ${s.chartWeek??Math.max(1,s.week-1)} · Individual songs · Weekly streams</p></div><span class="badge">${list.length} records</span></div><div class="highlightbox">Current #100: <strong>${fmt(list.at(-1)?.streams??CHART_FLOOR)} streams</strong><br><span class="fine">Entry requires at least ${fmt(CHART_FLOOR)} weekly streams and enough plays to beat the competition.</span></div>${s.songs.some(x=>x.released)?`<div class="your-chart"><h3>Your records</h3>${s.songs.filter(x=>x.released).slice().sort((a,b)=>b.streams-a.streams).map(x=>`<div class="row"><span>${esc(x.title)}</span><strong>${chartPosition(x)?'#'+chartPosition(x):'Uncharted'} · ${compact(x.streams)}</strong></div>`).join('')}</div>`:''}<table class="charttable"><thead><tr><th>#</th><th>Record / artist</th><th>Streams</th></tr></thead><tbody>${list.map((x,i)=>`<tr ${x.you?'style="color:var(--lime)"':''}><td>${i+1}</td><td><strong>${esc(x.title)}</strong><small>${esc(x.artist)} · ${x.tier}${x.you?' · YOU':''}</small></td><td>${compact(x.streams)}</td></tr>`).join('')}</tbody></table><p class="fine">This fictional streaming-only chart includes 150 wider-industry records beyond the feature roster. Competition changes weekly. Albums are not ranked against songs; these are game rules, not Billboard rules.</p></section>`}if(industryTab==='New releases')return top+`<section class="card"><h2>This week in music</h2>${s.feed.length?s.feed.slice(0,30).map(x=>`<div class="track"><span class="recordno">${x.type==='Album'?'ALB':'SGL'}</span><div><h3>${esc(x.title)}</h3><span class="fine">${esc(x.name)} · ${x.tier} · Week ${x.week}</span><p class="fine">${compact(x.streams)} debut streams · ${x.result}</p></div></div>`).join(''):'<p>The next releases arrive when you advance the week.</p>'}</section>`;return top+`<div class="chips">${['All',...tierNames].map(x=>`<button class="${filter===x?'selected':''}" onclick="filter='${x}';render()">${x}</button>`).join('')}</div><div class="roster-controls"><label>Genre <select onchange="genreFilter=this.value;render()">${['All',...genres].map(g=>`<option ${g===genreFilter?'selected':''}>${g}</option>`).join('')}</select></label><span class="fine">${s.world.filter(a=>(filter==='All'||tierNames[tier(a.fans)]===filter)&&(genreFilter==='All'||a.genre===genreFilter)).length} artists · Tap to meet</span></div><div class="artistgrid">${s.world.filter(a=>(filter==='All'||tierNames[tier(a.fans)]===filter)&&(genreFilter==='All'||a.genre===genreFilter)).map(a=>`<button class="artistcard" onclick="profile(${a.id})"><div class="initials">${a.name.split(' ').map(x=>x[0]).join('')}</div><span class="tier">${tierNames[tier(a.fans)]}</span><h3>${esc(a.name)}</h3><p>${esc(a.genre)} · ${compact(a.fans)} fans</p><p>${compact(a.catalog.reduce((n,x)=>n+x.streams,0))} streams / week</p><p class="rep-line">Reputation <strong>${fmt(a.reputation)}/100</strong></p><p class="${a.relation<0?'bad':''}">${relationship(a)} · ${a.relation>0?'+':''}${a.relation}</p><span class="feature-price">${a.relation<=-40?'Beef · unavailable':quote(a)?'Feature '+money(quote(a)):'Free feature'}</span><span class="fine">${accessible(a)?'Open to collaborate':'Career requirements apply'}</span></button>`).join('')}</div><section class="card" style="margin-top:20px"><h2>Different leagues. Same industry.</h2><p>Unknown → Emerging → Breakout → Star → Superstar → Global star → Global icon. Icons start at 100 million fans in this fictional world.</p><p class="fine">Stream totals depend on audience size, release quality, reception, promotion, features, and catalog age. Artists release new singles and albums on their own schedules.</p></section>`}
function artist(){return head('Identity & growth',esc(s.name)+'.',`<button class="secondary" onclick="setup()">Edit profile</button>`)+`<button class="training-launch" onclick="go('Training')"><span><strong>Training & stat improvement</strong><small>See your stats, choose an activity, and track your progress</small></span><span>Open training</span></button>`+`<section class="identity-banner"><span class="identity-monogram">${esc(s.name.slice(0,2).toUpperCase())}</span><div><span class="eyebrow">${esc(s.genre)} · Independent</span><h2>${tierNames[tier(s.fans)]}</h2><p>${compact(s.fans)} fans · Reputation ${s.reputation}/100</p></div></section>`+`<div class="grid"><section class="card"><span class="tier">${tierNames[tier(s.fans)]} · Independent</span><h2 style="margin-top:14px">${esc(s.genre)} · ${esc(s.background)}</h2>${[['Reputation',s.reputation],['Craft',s.skill],['Stage presence',s.stage],['Fan loyalty',s.loyalty],['Energy',s.energy]].map(([t,n])=>`<div class="sectionhead" style="margin:22px 0 0"><span>${t}</span><strong>${n}/100</strong></div><div class="bar"><i style="width:${n}%"></i></div>`).join('')}</section><section class="card" style="align-self:start"><h2>Your career so far</h2><p class="fine">Reputation grows through quality releases (+1 at quality 60+) and hits (+2). Public beef costs 2 reputation. Fame alone won’t unlock every collaboration.</p>${[['Weeks',s.week],['Released tracks',s.songs.filter(x=>x.released).length],['Albums',s.albums.length],['Lifetime streams',compact(s.total)],['Close relationships',s.world.filter(x=>x.relation>=60).length]].map(([k,v])=>`<div class="row"><span>${k}</span><strong>${v}</strong></div>`).join('')}<p class="fine">Playable simulation. Your career autosaves. Return with this browser to continue. Clearing cookies or switching browsers loses access to this guest save. No audio is generated. Economy values are game settings, not real-world income forecasts.</p><button class="secondary" onclick="resetAsk()">Start a new career</button></section></div>`}
function setup(){modal(`<div class="eyebrow">Your name on the marquee</div><h2>${s.started?'Your artist.':'Create your artist.'}</h2><form class="form" onsubmit="saveProfile(event)"><label>Stage name${nameInput('artistname','artist',s.name)}</label><label>Genre<select name="genre">${genres.map(x=>`<option ${s.genre===x?'selected':''}>${x}</option>`).join('')}</select></label>${s.started?'':`<label>Background<select name="bg"><option>Bedroom artist</option><option>Local performer</option><option>Online creator</option></select></label><p class="fine">Bedroom: 35 craft, 42 fans. Performer: 40 stage, 60 fans. Creator: 120 fans, 20 craft. Each starts with $650.</p>`}<button class="primary">${s.started?'Save profile':'Begin your career'}</button></form>`)}
function saveProfile(e){e.preventDefault();if(!saveReady||saveConflict)return;let f=new FormData(e.target);s.name=f.get('artistname').trim()||generate('artist');s.genre=f.get('genre');if(!s.started){s.background=f.get('bg');if(s.background==='Local performer'){s.stage=40;s.skill=25;s.fans=60}if(s.background==='Online creator'){s.fans=120;s.skill=20;s.stage=20}s.started=true}$('modal').close();render()}
function resetAsk(){modal(`<h2>A fresh start?</h2><p>This erases the current career and all relationships.</p><div class="controls"><button class="secondary" onclick="$('modal').close()">Keep playing</button><button class="primary" onclick="newCareer()">New career</button></div>`)}
// Reception varies independently of audience size. A hit is relative to expected reach.
function reception(quality){let r=Math.random(),luck=r<.15?rand(.3,.55):r>.9?rand(1.7,2.4):rand(.8,1.2);return Math.max(.15,luck*(.35+quality*.014))}
function worldWeek(){s.world.forEach(a=>{a.catalog.forEach(x=>{x.streams=Math.max(1,Math.round(x.streams*rand(.82,.96)));x.total+=x.streams});if(s.week>=a.nextRelease){let type=Math.random()<.25?'Album':'Single',factor=reception(a.skill),base=Math.round(a.fans*rand(.55,.85)*(type==='Album'?4:1)),streams=Math.round(base*factor),x={title:generate(type==='Album'?'album':'song'),type,week:s.week,base,factor,streams,total:streams};a.catalog.push(x);a.fans+=Math.round(streams*.009);a.reputation=clamp(a.reputation+(factor>=1.5?.4:factor<.65?-.3:0));s.feed.unshift({name:a.name,title:x.title,type,week:s.week,tier:tierNames[tier(a.fans)],streams,result:outcome(factor)});a.nextRelease=s.week+Math.round(rand(4,9));if(type==='Album'){let trackStreams=Math.round(streams*.25);a.catalog.push({title:generate('song'),type:'Single',week:s.week,base:Math.round(base*.25),factor,streams:trackStreams,total:trackStreams,fromAlbum:true});x.streams-=trackStreams;x.total-=trackStreams}}a.weekly=a.catalog.reduce((n,x)=>n+x.streams,0)});s.feed=s.feed.slice(0,60)}
function advance(confirmed=false){if(!saveReady||saveConflict)return;if(s.ap>0&&!confirmed){modal(`<h2>Finish the week?</h2><p>You have ${s.ap} unused time slot${s.ap===1?'':'s'}. They won’t carry over. Living costs of $100 will be charged.</p><div class="controls"><button class="secondary" onclick="$('modal').close()">Keep playing</button><button class="primary" onclick="$('modal').close();advance(true)">Finish week</button></div>`);return}let count=0,added=0,debut=[];s.songs.filter(x=>x.released).forEach(x=>{let n;if(x.factor===undefined){let guest=x.feature?s.world[x.feature.id]:null;let featureReach=guest?x.feature.fans*(guest.relation<=-40?.004:.018):0;x.base=reach(x);x.factor=reception(x.quality)*(x.mood.startsWith('Catchy')?1.2:x.mood.startsWith('Raw')?rand(.65,1.4):1)*(1+s.boost)*(x.albumBoost===s.week?1.15:1);x.launchFans=s.fans;n=Math.round(x.base*x.factor);x.organic=n/(1+s.boost)/(x.albumBoost===s.week?1.15:1);x.breakdown='Expected reach '+compact(x.base)+'; quality '+x.quality+'/100; '+x.mood.split(' /')[0].toLowerCase()+' direction'+(guest?'; guest '+guest.name:'')+'; promotion '+Math.round(s.boost*100)+'%. Audience reception helped determine the final '+x.factor.toFixed(2)+'× debut. '+(x.factor<.65?'Try improving your craft before your next recording.':x.factor>=1.5?'This release outperformed its expected audience.':'This release performed within the expected range.');s.reputation=clamp(s.reputation+(x.quality>=60?1:0)+(x.factor>=1.5?2:0));debut.push(x);log('“'+x.title+'” debuted with '+compact(n)+' streams: '+outcome(x.factor).toLowerCase()+'.')}else{let guest=x.feature?s.world[x.feature.id]:null;let conflict=guest&&guest.relation<=-40?.8:1;x.organic=Math.max(8,(x.organic??x.streams)*rand(.8,.94)+s.fans*.008);n=Math.round(x.organic*(1+s.boost)*conflict*(x.albumBoost===s.week?1.15:1))}x.streams=n;x.total+=n;count+=n;added+=Math.round(n*(x.mood.startsWith('Personal')?.026:.016)*(1+s.loyalty/200))});worldWeek();s.chartWeek=s.week;let rankings=chart();rankings.forEach((x,i)=>{if(x.you){let track=s.songs.find(y=>y.id===x.id);track.peak=Math.min(track.peak||Infinity,i+1)}});s.streams=count;s.total+=count;s.fans+=added;let royalties=Math.round(count*.50*100)/100;s.cash=Math.round((s.cash+royalties-100)*100)/100;s.energy=clamp(s.energy+40);if(added)s.loyalty=clamp(s.loyalty+1);s.lastReport={streams:count,fans:added,royalties,debut:debut.map(x=>x.id)};let completed=s.week;s.week++;s.ap=6;s.boost=0;log(count?compact(count)+' streams, '+fmt(added)+' new fans, and '+money(royalties)+' in royalties.':'A fresh week. New records are dropping around you.');if(s.cash<0)log('Your balance is below zero. Work shifts can cover the shortfall.');render();modal(`<div class="eyebrow">Week ${completed} · Wrapped</div><h2>${debut.length?'Your music has landed.':count?'They kept listening.':'The industry keeps moving.'}</h2>${[['Weekly streams',compact(count)],['New fans','+'+fmt(added)],['Royalties',money(royalties)],['Living costs','−$100'],['Cash balance',money(s.cash)]].map(([k,v])=>`<div class="row"><span>${k}</span><strong>${v}</strong></div>`).join('')}${debut.map(x=>`<div class="highlightbox"><strong>${esc(x.title)}</strong><br>${outcome(x.factor)} · ${x.factor.toFixed(1)}× expected reach · ${compact(x.streams)} streams${chartPosition(x)?' · Chart #'+chartPosition(x):' · Uncharted'}<p class="fine">${esc(x.breakdown)}</p></div>`).join('')}<p class="fine">Rivals released ${s.feed.filter(x=>x.week===completed).length} new projects. Six time slots restored; up to 40 energy recovered.</p><button class="primary" style="width:100%;margin-top:10px" onclick="$('modal').close()">Start week ${s.week}</button>`)}
function reach(track){let guest=track.feature?s.world[track.feature.id]:null;let featureReach=guest?track.feature.fans*(guest.relation<=-40?.004:.018)*(guest.genre===s.genre?1:.8):0;return Math.round(180+s.fans*.9+featureReach)}
function nextStep(){let heading,text,button,handler;
if(!s.started){heading='Start with one record';text='Create your artist, then write, record, mix, and release a single. Each week gives you six time slots.';button='Create artist';handler='setup()'}
else if(s.cash<100){heading='Give yourself some runway';text='Living costs are $100 each week. A work shift earns $180, even when your balance is negative.';button='Work a shift';handler="action('work')"}
else if(s.energy<15){heading='Take a breather';text='Rest restores 30 energy for one time slot. A new week restores up to 40 energy.';button='Rest';handler="action('rest')"}
else if(s.draft){heading=['','Put down the vocals','Give it a final mix','Your record is ready'][s.draft.steps];text=s.draft.steps===3?'Release it now for $20 or save it for an album.':'You can pause a project and continue next week. Your work stays in the studio.';button='Continue record';handler="go('Studio')"}
else if(!s.songs.some(x=>x.released)){heading='Make your first single';text='Budget $90 and four time slots to go from idea to release. You can work on it over more than one week.';button='Open studio';handler="go('Studio')"}
else if(s.songs.some(x=>x.released&&x.factor===undefined)){heading='Your debut is on the way';text='Advance the week to see the results. If you still have time, practice, rest, or work a shift.';button='Review releases';handler="go('Career')"}
else if(s.week<=8){heading='Build a rhythm that works';text='Work covers bills. Practice improves future records. Open mics grow your first audience. You don’t need a feature or an album yet.';button='Review your results';handler="go('Career')"}
else return '';
return `<section class="card guide"><div><span class="eyebrow">Your next step</span><h3>${heading}</h3><p>${text}</p></div><button class="secondary" onclick="${handler}">${button}</button></section>`}

function exactCash(n){return new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n)}
function homeStats(){let report=s.lastReport;return `<section class="home-dashboard" aria-label="Career overview"><div class="overview-numbers">${[
['cash','Cash',s.cash<0?'−$'+compact(-s.cash):'$'+compact(s.cash),s.cash<100?'Below weekly bills':'$100 weekly bills',s.cash<100],
['fans','True fans',compact(s.fans),report?'+'+fmt(report.fans)+' last week':'Building your audience',false],
['streams','Streams',compact(s.streams),s.week>1?'Week '+(s.week-1)+' results':'First results pending',false]
].map(([key,label,value,note,low])=>`<button class="overview-stat ${low?'overview-low':''}" onclick="statDetail('${key}')" aria-label="${label}: ${key==='cash'?exactCash(s.cash):fmt(key==='fans'?s.fans:s.streams)}. View details"><span class="overview-label">${label}</span><strong>${value}</strong><span class="overview-note">${note}</span></button>`).join('')}</div><div class="overview-resources"><button onclick="statDetail('energy')" class="resource-item ${s.energy<20?'overview-low':''}"><span>Energy <strong>${s.energy}/100</strong></span><span class="resource-meter" aria-hidden="true"><i style="width:${s.energy}%"></i></span></button><button onclick="statDetail('time')" class="resource-item"><span>Time left <strong>${s.ap}/6 slots</strong></span><span class="time-slots" aria-hidden="true">${Array.from({length:6},(_,i)=>`<i class="${i<s.ap?'filled':''}"></i>`).join('')}</span></button></div><div class="overview-caption">Tap a stat for the full breakdown</div></section>`}
function statDetail(key){let r=s.lastReport;let titles={cash:'Your cash',fans:'Your audience',streams:'Your streams',energy:'Your energy',time:'Your week'};let rows,description;
if(key==='cash'){rows=[['Available balance',exactCash(s.cash)],['Living costs each week','$100.00'],['Last week’s royalties',r?exactCash(r.royalties):'No results yet'],['Current royalty rate','$0.50 per stream'],['Work shift income','$180.00']];description='Available cash includes your actions so far. Living costs are charged when you advance the week. Royalties are streaming income only, not total weekly profit.'}
if(key==='fans'){rows=[['True fans',fmt(s.fans)],['New fans from last week’s streams',r?'+'+fmt(r.fans):'No results yet'],['Career tier',tierNames[tier(s.fans)]],['Fan loyalty',s.loyalty+'/100']];description='Fans are people who support your artist. Streams count plays, so one fan can generate more than one stream. Open-mic fans join immediately; the weekly figure only counts fans from streaming.'}
if(key==='streams'){rows=[['Last completed week',s.week>1?'Week '+(s.week-1):'None yet'],['Streams that week',fmt(s.streams)],['Lifetime streams',fmt(s.total)],['Released tracks',fmt(s.songs.filter(x=>x.released).length)],['Campaign this week',s.boost>0?'+35% streaming boost':'No campaign']];description='Streams update after you advance the week. These totals combine all your released tracks. Album tracks are counted once.'}
if(key==='energy'){rows=[['Energy available',s.energy+'/100'],['Rest action','+30 · 1 time slot'],['New week recovery','Up to +40'],['Writing / recording / mixing','−10 / −15 / −15']];description='Energy limits how much work you can take on. Rest can restore energy now; recovery cannot take you above 100.'}
if(key==='time'){rows=[['Time available',s.ap+' of 6 slots'],['Slots already used',6-s.ap],['New week','6 fresh slots'],['Unused slots','Do not carry over']];description='Most actions take one slot. Making and releasing a single takes four in total, which you can spread across weeks. Advancing the week also charges $100 in living costs.'}
modal(`<div class="eyebrow">Career overview</div><h2>${titles[key]}</h2>${rows.map(([label,value])=>`<div class="row"><span>${label}</span><strong>${value}</strong></div>`).join('')}<p>${description}</p>`)}


function metricRail(items){return `<div class="metric-rail">${items.map(([l,v])=>`<div><span>${l}</span><strong>${v}</strong></div>`).join('')}</div>`}
function saveStatus(message,error=false){let el=$('save-status');el.textContent=message;el.className='save-status'+(error?' error':'')}
function queueSave(){if(!saveReady||saveConflict||JSON.stringify(s)===lastSaved)return;saveStatus('Unsaved changes');clearTimeout(saveTimer);saveTimer=setTimeout(saveNow,250)}
async function saveNow(){clearTimeout(saveTimer);if(!saveReady||saveConflict||saveBusy)return;const snapshot=JSON.stringify(s);if(snapshot===lastSaved){saveStatus('Career saved ✓');return}saveBusy=true;saveStatus('Saving…');try{let response=await fetch('/api/save',{method:'PUT',headers:{'Content-Type':'application/json',...(saveEtag?{'If-Match':saveEtag}:{'If-None-Match':'*'})},body:JSON.stringify({schemaVersion:1,state:JSON.parse(snapshot)}),keepalive:snapshot.length<55000});if(response.status===409){saveConflict=true;throw Error('A different tab saved this career. Reload to continue.')}if(!response.ok)throw Error('Save failed. Keep this tab open and tap Retry save.');let result=await response.json();saveEtag=result.etag;lastSaved=snapshot;saveStatus('Career saved ✓')}catch(e){saveStatus(saveConflict?'Other tab saved · reload':'Retry save',true);toast(e.message)}finally{saveBusy=false;if(!saveConflict&&lastSaved===snapshot&&JSON.stringify(s)!==lastSaved)queueSave()}}
async function boot(){saveStatus('Loading career…');try{let response=await fetch('/api/save',{cache:'no-store'});if(!response.ok)throw Error('Your saved career could not be loaded.');let data=await response.json();if(data.save){if(data.save.schemaVersion!==1)throw Error('This career needs a newer game version. Reload to update.');let loaded=data.save.state;if(!loaded||!Array.isArray(loaded.world)||!Number.isFinite(loaded.week))throw Error('The saved career could not be read.');s=loaded;lastSaved=JSON.stringify(s);migrateCharts();migratePacing()}saveEtag=data.etag;saveReady=true;$('save-status').onclick=saveNow;render();if(lastSaved===JSON.stringify(s))saveStatus('Career restored ✓');else await saveNow()}catch(e){saveReady=false;saveStatus('Retry loading',true);$('save-status').onclick=boot;$('app').innerHTML=`<section class="card"><h2>Let’s protect your progress.</h2><p>${esc(e.message)} Your existing save has not been replaced.</p><button class="primary" onclick="boot()">Try again</button></section>`}}
async function newCareer(){if(saveBusy){toast('Wait for the current save to finish.');return}if(saveConflict){toast('Reload this tab before starting a new career.');return}s=fresh();tab='Home';$('modal').close();render();await saveNow();setup()}
window.addEventListener('beforeunload',e=>{if(saveReady&&JSON.stringify(s)!==lastSaved){e.preventDefault();e.returnValue=''}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')saveNow()});
function migratePacing(){if(s.pacingVersion===1)return;s.ap=Math.min(6,Math.max(0,s.ap)+2);s.pacingVersion=1;log('Update: six slots per week, +40 weekly energy, and $0.50 per future stream. Two extra slots added this week.');}
function training(){const options=[{name:'Craft',value:s.skill,benefit:'Better writing and recording improve the quality of future songs.',gain:Math.min(4,100-s.skill),energy:10,action:'practice',button:'Practice your craft',extra:'No cash cost',capped:s.skill>=100},{name:'Stage presence',value:s.stage,benefit:'Build performance experience through open mics. Stage presence is tracked; it does not yet change gig payouts.',gain:Math.min(3,100-s.stage),energy:20,action:'gig',button:'Play an open mic',extra:'Earn $30 and gain 8 fans',capped:false}];return head('Artist development','Training.',`<button class="secondary" onclick="go('Artist')">Artist profile</button>`)+metricRail([['Time',s.ap+' / 6 slots'],['Energy',s.energy+' / 100'],['Craft',s.skill+' / 100'],['Stage',s.stage+' / 100']])+`<div class="training-grid">${options.map(o=>{let reason=o.capped?'Maximum reached':s.ap<1?'No time slots left':s.energy<o.energy?'Rest to recover energy':'';return `<section class="card training-card"><div class="sectionhead"><h2>${o.name}</h2><span class="training-score">${o.value}<small>/100</small></span></div><div class="bar"><i style="width:${o.value}%"></i></div><p>${o.benefit}</p><div class="training-gain">${o.gain?'+'+o.gain+' '+o.name.toLowerCase():'Stat at maximum'} <span>${o.value} → ${Math.min(100,o.value+o.gain)}</span></div><p class="fine">1 time slot · ${o.energy} energy · ${o.extra}</p><button class="primary" ${reason?'disabled':''} onclick="action('${o.action}')">${o.button}</button>${reason?`<p class="fine">${reason}</p>`:''}</section>`}).join('')}</div><section class="card training-rest"><div><h3>Need energy?</h3><p class="fine">Rest restores up to 30 energy for 1 slot. A new week restores up to 40.</p></div><button class="secondary" ${s.energy>=100||s.ap<1?'disabled':''} onclick="action('rest')">Rest · +${Math.min(30,100-s.energy)} energy</button></section><h2>Stats earned through your career</h2><p>These improve through results, rather than a practice session.</p><div class="training-grid"><section class="card"><div class="sectionhead"><h3>Reputation</h3><strong>${s.reputation}/100</strong></div><div class="bar"><i style="width:${s.reputation}%"></i></div><p>Earn +1 when a record debuts at quality 60 or higher, and +2 when its debut is a hit. Both can apply. Public beef costs 2 reputation.</p><button class="secondary" onclick="go('Studio')">Make a record</button></section><section class="card"><div class="sectionhead"><h3>Fan loyalty</h3><strong>${s.loyalty}/100</strong></div><div class="bar"><i style="width:${s.loyalty}%"></i></div><p>Gain +1 in a week when your music attracts new fans. Higher loyalty improves fan conversion. Public beef costs 2 loyalty.</p><button class="secondary" onclick="go('Career')">View your releases</button></section></div>`}
boot();
